    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()

# Clean derivation: find exact affine mapping per demo, then build rule.
for i in [1,2,3]:
    inp=G[f'Demo pair {i} input']; out=G[f'Demo pair {i} output']
    S={(r,c):inp[r][c] for r in range(len(inp)) for c in range(len(inp[0])) if inp[r][c]==4}
    A={(r,c):out[r][c] for r in range(len(out)) for c in range(len(out[0])) if out[r][c]==4 and inp[r][c]!=4}
    mk=[(r,c) for r in range(len(inp)) for c in range(len(inp[0])) if inp[r][c]==6]
    mr=[r for _,_ in mk]; mc=[c for _,c in mk]
    print('demo',i,'shape bbox',(min(r for r,_ in S),max(r for r,_ in S),min(c for _,c in S),max(c for _,c in S)))
    print('  marker bbox',(min(mr),max(mr),min(mc),max(mc)))
    sols=[]
    for a in (-1,1):
        for cc in (-1,1):
            for b in range(-8,15):
                for de in range(-8,15):
                    m={(a*s+b,cc*c+de):v for s,v in S.items()}
                    if m==A: sols.append((a,b,cc,de))
    print('  exact mappings:',sols)

